#![allow(unused_imports)]
use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// Given two equally‐long vectors `a` and `b` of `i8`, returns
    /// a `Vec<bool>` `result` of the same length such that
    /// result[i] == (a[i] <= b[i]) for all valid indices `i`.
    fn less_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            // The two input vectors must have equal length
            a.len() == b.len()
        ensures
            // The output vector has the same length as the inputs
            result.len() == a.len()
        ensures
            // For each index i, result[i] holds the boolean of a[i] <= b[i]
            forall |i: usize| i < a.len() ==> result[i] == (a[i] <= b[i])
    {
        let mut result: Vec<bool> = Vec::new();
        let n: usize = a.len();
        // Pre‐allocate the needed capacity
        result.reserve(n);

        let mut i: usize = 0;
        while i < n
            invariant
                // Loop index stays within bounds
                i <= n,
            invariant
                // We have pushed exactly i elements so far
                result.len() == i,
            invariant
                // For all j < i, the property holds:
                // result[j] == (a[j] <= b[j])
                forall |j: usize| j < i ==> result[j] == (a[j] <= b[j]),
            decreases
                // A well‐founded measure ensures termination
                n - i
        {
            let comparison: bool = a[i] <= b[i];
            result.push(comparison);
            i += 1;
        }

        result
    }

}